add_action( 'storefront_before_header', 'perfectpixel_storefront_top_bar' );

function perfectpixel_storefront_top_bar() {
	$bg = sanitize_hex_color( '{{storefront_top_bar_bg}}' );
	printf(
		'<div class="perfectpixel-top-bar" style="background:%s;color:#fff;text-align:center;font-size:.85em;padding:.5em 1em">%s</div>',
		esc_attr( $bg ? $bg : '#1d2327' ),
		wp_kses_post( '{{storefront_top_bar_text}}' )
	);
}
